"""Host integration tests use generated bytes only; no game assets are read."""
import hashlib
from pathlib import Path
import subprocess
import tempfile
import unittest

HERE = Path(__file__).resolve().parent
IDENT = 'a' * 64

class PrepareTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.build = tempfile.TemporaryDirectory()
        cls.binary = Path(cls.build.name) / 'prepare'
        subprocess.run(['clang', '-DTCG_HOST', '-std=c11', '-Wall', '-Wextra',
                        '-Werror', '-Wno-deprecated-declarations',
                        str(HERE / 'bootstrap/source/tcg_prepare.c'),
                        str(HERE / 'host_prepare.c'), '-o', str(cls.binary)], check=True)

    @classmethod
    def tearDownClass(cls):
        cls.build.cleanup()

    def setUp(self):
        self.tmp = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmp.cleanup)
        self.root = Path(self.tmp.name)
        self.payload = self.root / 'payload'
        self.payload.mkdir()
        self.stage = self.root / 'stage'
        self.dest = self.root / 'wine'
        self.manifest = self.root / 'manifest.tsv'
        self.files = {'runtime.nro': b'nro' * 100000,
                      'drive_c/TCG_Autorun_Test/game.exe': b'fake executable',
                      'config.ini': b'initial settings',
                      'drive_c/users/player/save.dat': b'initial save'}
        for name, data in self.files.items():
            path = self.payload / name
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(data)
        self.write_manifest()

    def write_manifest(self, rows=None, total=None, count=None):
        if rows is None:
            rows = [f'{hashlib.sha256(data).hexdigest()}\t{len(data)}\t{name}'
                    for name, data in self.files.items()]
        self.manifest.write_text(f'TCG-COMPAT-1\t{IDENT}\t{sum(map(len, self.files.values())) if total is None else total}\t{len(rows) if count is None else count}\n' + '\n'.join(rows) + '\n')

    def run_prepare(self, fail=0):
        args = [str(self.binary), str(self.payload), str(self.manifest), str(self.stage), str(self.dest)]
        if fail:
            args += ['--fail-after', str(fail)]
        return subprocess.run(args, capture_output=True, text=True)

    def assert_refused(self):
        result = self.run_prepare()
        self.assertNotEqual(result.returncode, 0)
        self.assertTrue(result.stderr.strip())
        self.assertFalse((self.dest / '.tcg-compat-installed').exists())

    def test_first_prepare_and_reuse_preserve_mutable_data(self):
        self.assertEqual(self.run_prepare().returncode, 0)
        self.assertFalse(self.stage.exists())
        self.assertEqual((self.dest / '.tcg-compat-installed').read_text().strip(), IDENT)
        for name, data in self.files.items():
            self.assertEqual((self.dest / name).read_bytes(), data)
        for name in ['config.ini', 'drive_c/users/player/save.dat']:
            (self.dest / name).write_bytes(b'user modified')
        self.assertEqual(self.run_prepare().returncode, 0)
        self.assertEqual((self.dest / 'config.ini').read_bytes(), b'user modified')
        self.assertEqual((self.dest / 'drive_c/users/player/save.dat').read_bytes(), b'user modified')

    def test_interrupted_copy_retains_owned_stage_and_resumes(self):
        self.assertNotEqual(self.run_prepare(1000).returncode, 0)
        self.assertFalse(self.dest.exists())
        self.assertEqual((self.stage / '.tcg-stage-owner').read_text().strip(), IDENT)
        self.assertFalse((self.stage / '.tcg-compat-installed').exists())
        self.assertEqual(self.run_prepare().returncode, 0)
        self.assertEqual((self.dest / 'runtime.nro').read_bytes(), self.files['runtime.nro'])

    def test_unsafe_paths(self):
        for name in ['/escape', '../escape', 'a/../escape', 'a\\escape', 'a//b', './escape']:
            with self.subTest(name=name):
                self.write_manifest([f'{"0" * 64}\t0\t{name}'], total=0)
                self.assert_refused()

    def test_wrong_hash(self):
        (self.payload / 'runtime.nro').write_bytes(b'bad' * 100000)
        self.assert_refused()
        self.assertFalse((self.stage / '.tcg-compat-installed').exists())

    def test_unowned_destination_preserved(self):
        self.dest.mkdir()
        (self.dest / 'precious').write_text('keep')
        self.assert_refused()
        self.assertEqual((self.dest / 'precious').read_text(), 'keep')

    def test_unowned_stage_preserved(self):
        self.stage.mkdir()
        (self.stage / 'precious').write_text('keep')
        self.assert_refused()
        self.assertEqual((self.stage / 'precious').read_text(), 'keep')

    def test_symlink_escape(self):
        outside = self.root / 'outside'
        outside.mkdir()
        self.stage.mkdir()
        (self.stage / '.tcg-stage-owner').write_text(IDENT + '\n')
        (self.stage / 'drive_c').symlink_to(outside, target_is_directory=True)
        self.assert_refused()
        self.assertEqual(list(outside.iterdir()), [])

    def test_destination_symlink_refused(self):
        outside = self.root / 'outside'
        outside.mkdir()
        (outside / '.tcg-compat-installed').write_text(IDENT + '\n')
        self.dest.symlink_to(outside, target_is_directory=True)
        self.assertNotEqual(self.run_prepare().returncode, 0)
        self.assertEqual(list(outside.iterdir()), [outside / '.tcg-compat-installed'])

    def test_incomplete_manifest_count_or_sum(self):
        for kwargs in [{'count': 99}, {'total': 1}]:
            with self.subTest(kwargs=kwargs):
                self.write_manifest(**kwargs)
                self.assert_refused()

    def test_ready_immutable_missing_refused(self):
        self.assertEqual(self.run_prepare().returncode, 0)
        (self.dest / 'drive_c/TCG_Autorun_Test/game.exe').unlink()
        self.assertNotEqual(self.run_prepare().returncode, 0)

    def test_generic_game_configuration_is_mutable(self):
        name = 'drive_c/TCG_Autorun_Test/settings.ini'
        self.files[name] = b'initial game configuration'
        (self.payload / name).write_bytes(self.files[name])
        self.write_manifest()
        self.assertEqual(self.run_prepare().returncode, 0)
        (self.dest / name).write_bytes(b'changed')
        self.assertEqual(self.run_prepare().returncode, 0)
        self.assertEqual((self.dest / name).read_bytes(), b'changed')

    def test_temp_suffix_payload_does_not_collide_with_copy(self):
        self.files = {'runtime.nro.tmp': b'payload with tmp suffix', **self.files}
        (self.payload / 'runtime.nro.tmp').write_bytes(self.files['runtime.nro.tmp'])
        self.write_manifest()
        self.assertEqual(self.run_prepare().returncode, 0)
        self.assertEqual((self.dest / 'runtime.nro.tmp').read_bytes(), b'payload with tmp suffix')

    def test_source_symlink_refused(self):
        source = self.payload / 'runtime.nro'
        source.unlink()
        outside = self.root / 'outside'
        outside.write_bytes(self.files['runtime.nro'])
        source.symlink_to(outside)
        self.assert_refused()

    def test_staged_file_symlink_refused(self):
        self.stage.mkdir()
        (self.stage / '.tcg-stage-owner').write_text(IDENT + '\n')
        outside = self.root / 'outside'
        outside.write_bytes(b'keep')
        (self.stage / 'runtime.nro').symlink_to(outside)
        self.assert_refused()
        self.assertEqual(outside.read_bytes(), b'keep')

    def test_corrupt_staged_file_is_repaired(self):
        self.stage.mkdir()
        (self.stage / '.tcg-stage-owner').write_text(IDENT + '\n')
        (self.stage / 'runtime.nro').write_bytes(b'x' * len(self.files['runtime.nro']))
        self.assertEqual(self.run_prepare().returncode, 0)
        self.assertEqual((self.dest / 'runtime.nro').read_bytes(), self.files['runtime.nro'])

    def test_ready_runtime_missing_or_resized_refused(self):
        self.assertEqual(self.run_prepare().returncode, 0)
        (self.dest / 'runtime.nro').write_bytes(b'truncated')
        self.assertNotEqual(self.run_prepare().returncode, 0)

    def test_game_profiles_and_logs_are_mutable_but_data_is_checked(self):
        prefix = 'drive_c/TCG_Autorun_Test/'
        for name in ['TCG Autorun Test.args.txt', 'TCG Autorun Test.keys.txt',
                     'TCG Autorun Test.wine-nx.json', 'runtime.log',
                     'TCG Autorun Test_Data/bundle']:
            self.files[prefix + name] = b'synthetic initial data'
            path = self.payload / (prefix + name)
            path.parent.mkdir(parents=True, exist_ok=True)
            path.write_bytes(self.files[prefix + name])
        self.write_manifest()
        self.assertEqual(self.run_prepare().returncode, 0)
        for name in ['TCG Autorun Test.args.txt', 'TCG Autorun Test.keys.txt',
                     'TCG Autorun Test.wine-nx.json', 'runtime.log']:
            (self.dest / (prefix + name)).write_bytes(b'changed')
        self.assertEqual(self.run_prepare().returncode, 0)
        (self.dest / (prefix + 'TCG Autorun Test_Data/bundle')).unlink()
        self.assertNotEqual(self.run_prepare().returncode, 0)

    def test_switch_fsdev_file_handles_and_staged_repair(self):
        # Compile the Switch branch with a host crypto adapter and emulate the
        # fsdev file-open and rename boundaries: no directory descriptors and
        # no rename-over-existing behavior.
        shim = self.root / 'shim'
        shim.mkdir()
        (shim / 'switch.h').write_text("""
#include <CommonCrypto/CommonDigest.h>
typedef CC_SHA256_CTX Sha256Context;
#define sha256ContextCreate(h) CC_SHA256_Init(h)
#define sha256ContextUpdate(h,p,n) CC_SHA256_Update(h,p,(CC_LONG)(n))
#define sha256ContextGetHash(h,p) CC_SHA256_Final(p,h)
""")
        (shim / 'fsdev.c').write_text("""
#include <errno.h>
#include <fcntl.h>
#include <stdarg.h>
#include <stdio.h>
#include <sys/stat.h>
int tcg_fsdev_open(const char *path, int flags, ...) {
    struct stat st;
    if (!stat(path, &st) && S_ISDIR(st.st_mode)) { errno = EISDIR; return -1; }
    int mode = 0;
    if (flags & O_CREAT) {
        va_list args; va_start(args, flags); mode = va_arg(args, int); va_end(args);
    }
    return open(path, flags, mode);
}
int tcg_fsdev_rename(const char *from, const char *to) {
    struct stat st;
    if (!lstat(to, &st)) { errno = EEXIST; return -1; }
    return rename(from, to);
}
""")
        obj = shim / 'core.o'
        subprocess.run(['clang', '-std=c11', '-Wall', '-Wextra', '-Werror',
                        '-Wno-deprecated-declarations', '-I', str(shim),
                        '-Dopen=tcg_fsdev_open', '-Drename=tcg_fsdev_rename', '-c',
                        str(HERE / 'bootstrap/source/tcg_prepare.c'), '-o', str(obj)], check=True)
        binary = shim / 'prepare-switch-shim'
        subprocess.run(['clang', str(obj), str(shim / 'fsdev.c'),
                        str(HERE / 'host_prepare.c'), '-o', str(binary)], check=True)
        self.binary = binary
        self.stage.mkdir()
        (self.stage / '.tcg-stage-owner').write_text(IDENT + '\n')
        (self.stage / 'runtime.nro').write_bytes(b'corrupt staged content')
        result = self.run_prepare()
        self.assertEqual(result.returncode, 0, result.stderr)
        self.assertEqual((self.dest / 'runtime.nro').read_bytes(), self.files['runtime.nro'])

    def test_fat32_limit(self):
        self.write_manifest([f'{"0" * 64}\t4294967296\truntime.nro'], total=4294967296)
        self.assert_refused()

if __name__ == '__main__':
    unittest.main()
